const state = {
  dashboard: null,
  checkpoints: [],
  selectedSessionId: null,
};

const els = {
  apiBase: document.querySelector("#apiBase"),
  refresh: document.querySelector("#refresh"),
  status: document.querySelector("#status"),
  totalSessions: document.querySelector("#totalSessions"),
  activeSessions: document.querySelector("#activeSessions"),
  readySessions: document.querySelector("#readySessions"),
  needsReview: document.querySelector("#needsReview"),
  statusFilter: document.querySelector("#statusFilter"),
  riskFilter: document.querySelector("#riskFilter"),
  sessionList: document.querySelector("#sessionList"),
  emptyState: document.querySelector("#emptyState"),
  sessionDetail: document.querySelector("#sessionDetail"),
  sessionMeta: document.querySelector("#sessionMeta"),
  sessionTitle: document.querySelector("#sessionTitle"),
  riskBadge: document.querySelector("#riskBadge"),
  riskMeter: document.querySelector("#riskMeter"),
  intentMeter: document.querySelector("#intentMeter"),
  handoffSummary: document.querySelector("#handoffSummary"),
  blockers: document.querySelector("#blockers"),
  suggestions: document.querySelector("#suggestions"),
  checkpointCount: document.querySelector("#checkpointCount"),
  fileCount: document.querySelector("#fileCount"),
  todoCount: document.querySelector("#todoCount"),
  intentSummary: document.querySelector("#intentSummary"),
  checkpointList: document.querySelector("#checkpointList"),
};

function defaultApiBase() {
  if (window.location.protocol === "http:" || window.location.protocol === "https:") {
    return window.location.origin;
  }
  return "http://localhost:8000";
}

function apiBase() {
  return els.apiBase.value.replace(/\/+$/, "");
}

async function getJson(path) {
  const response = await fetch(`${apiBase()}${path}`);
  if (!response.ok) {
    throw new Error(`${path} returned ${response.status}`);
  }
  return response.json();
}

function setStatus(message, isError = false) {
  els.status.textContent = message;
  els.status.classList.toggle("error", isError);
}

function formatDate(value) {
  if (!value) {
    return "unknown time";
  }
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return value;
  }
  return date.toLocaleString();
}

function shortId(id) {
  return id ? id.slice(0, 12) : "unknown";
}

function renderList(items, values) {
  items.replaceChildren();
  if (!values.length) {
    const li = document.createElement("li");
    li.textContent = "None";
    items.append(li);
    return;
  }
  for (const value of values) {
    const li = document.createElement("li");
    li.textContent = value;
    items.append(li);
  }
}

function filteredSessions() {
  const sessions = state.dashboard?.sessions || [];
  const status = els.statusFilter.value;
  const risk = els.riskFilter.value;
  return sessions.filter((session) => {
    const statusMatch = status === "all" || session.status === status;
    const riskMatch = risk === "all" || session.risk_level === risk;
    return statusMatch && riskMatch;
  });
}

function renderSummary() {
  const dashboard = state.dashboard || {};
  els.totalSessions.textContent = dashboard.total_sessions ?? 0;
  els.activeSessions.textContent = dashboard.active_sessions ?? 0;
  els.readySessions.textContent = dashboard.ready_for_handoff ?? 0;
  els.needsReview.textContent = dashboard.needs_review ?? 0;
}

function renderSessions() {
  const sessions = filteredSessions();
  els.sessionList.replaceChildren();

  if (!sessions.length) {
    const empty = document.createElement("div");
    empty.className = "session-button";
    empty.textContent = "No sessions match the current filters.";
    els.sessionList.append(empty);
    renderDetail(null);
    return;
  }

  if (!sessions.some((session) => session.session_id === state.selectedSessionId)) {
    state.selectedSessionId = sessions[0].session_id;
  }

  for (const session of sessions) {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "session-button";
    button.classList.toggle("selected", session.session_id === state.selectedSessionId);

    const row = document.createElement("div");
    row.className = "session-row";

    const title = document.createElement("span");
    title.className = "session-title";
    title.textContent = session.description || session.first_prompt || session.session_id;

    const badge = document.createElement("span");
    badge.className = `badge risk-${session.risk_level}`;
    badge.textContent = session.risk_level;

    const subtitle = document.createElement("div");
    subtitle.className = "session-subtitle";
    subtitle.textContent = `${session.status} / ${session.agent_type || "unknown agent"} / ${session.checkpoint_count} checkpoints`;

    row.append(title, badge);
    button.append(row, subtitle);
    button.addEventListener("click", () => {
      state.selectedSessionId = session.session_id;
      renderSessions();
      renderDetail(session);
    });
    els.sessionList.append(button);
  }

  renderDetail(sessions.find((session) => session.session_id === state.selectedSessionId) || sessions[0]);
}

function renderDetail(session) {
  if (!session) {
    els.emptyState.classList.remove("hidden");
    els.sessionDetail.classList.add("hidden");
    return;
  }

  els.emptyState.classList.add("hidden");
  els.sessionDetail.classList.remove("hidden");
  els.sessionMeta.textContent = `${session.status} / ${session.agent_type || "unknown agent"} / ${formatDate(session.start_time)}`;
  els.sessionTitle.textContent = session.description || session.first_prompt || session.session_id;
  els.riskBadge.className = `badge risk-${session.risk_level}`;
  els.riskBadge.textContent = session.risk_level;
  els.riskMeter.value = session.risk_score;
  els.intentMeter.value = session.intent_alignment;
  els.handoffSummary.textContent = session.handoff_summary;
  renderList(els.blockers, session.handoff_blockers || []);
  renderList(els.suggestions, session.handoff_suggestions || []);
  els.checkpointCount.textContent = `${session.checkpoint_count} checkpoints`;
  els.fileCount.textContent = `${(session.files_changed || []).length} files`;
  els.todoCount.textContent = `${session.todos_count || 0} todos`;
  els.intentSummary.textContent = session.intent_summary || "No intent summary available.";
  renderCheckpoints(session.session_id);
}

function renderCheckpoints(sessionId) {
  const checkpoints = state.checkpoints.filter((checkpoint) => checkpoint.session_id === sessionId);
  els.checkpointList.replaceChildren();

  if (!checkpoints.length) {
    const empty = document.createElement("p");
    empty.className = "summary-text";
    empty.textContent = "No checkpoints returned for this session.";
    els.checkpointList.append(empty);
    return;
  }

  for (const checkpoint of checkpoints) {
    const item = document.createElement("article");
    item.className = "checkpoint";

    const title = document.createElement("h4");
    title.textContent = checkpoint.message || shortId(checkpoint.id);

    const meta = document.createElement("span");
    meta.className = "checkpoint-meta";
    meta.textContent = `${shortId(checkpoint.id)} / ${formatDate(checkpoint.timestamp)}`;

    const files = document.createElement("p");
    files.textContent = checkpoint.files_changed?.length
      ? `Files: ${checkpoint.files_changed.slice(0, 6).join(", ")}`
      : "Files: not included in checkpoint list JSON";

    item.append(title, meta, files);
    els.checkpointList.append(item);
  }
}

async function loadDashboard() {
  setStatus("Loading dashboard data...");
  els.refresh.disabled = true;
  try {
    const [dashboard, checkpoints] = await Promise.all([
      getJson("/api/dashboard"),
      getJson("/api/checkpoints"),
    ]);
    state.dashboard = dashboard;
    state.checkpoints = checkpoints;
    if (!state.selectedSessionId && dashboard.sessions?.length) {
      state.selectedSessionId = dashboard.sessions[0].session_id;
    }
    renderSummary();
    renderSessions();
    setStatus(`Loaded ${dashboard.total_sessions} sessions from ${apiBase()}.`);
  } catch (error) {
    setStatus(error.message, true);
  } finally {
    els.refresh.disabled = false;
  }
}

els.apiBase.value = new URLSearchParams(window.location.search).get("api") || defaultApiBase();
els.refresh.addEventListener("click", loadDashboard);
els.statusFilter.addEventListener("change", renderSessions);
els.riskFilter.addEventListener("change", renderSessions);

loadDashboard();

:root {
