  width: min(1440px, 100%);
  min-height: 100vh;
  margin: 0 auto;
  padding: 24px;
}

.topbar {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 16px;
}

.eyebrow {
  margin: 0 0 4px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: uppercase;
}

h1,
h2,
h3,
h4,
p {
  overflow-wrap: anywhere;
}

h1 {
  margin: 0;
  font-size: 28px;
  line-height: 1.1;
}

h2 {
  margin: 0;
  font-size: 20px;
  line-height: 1.2;
}

h3 {
  margin: 0 0 10px;
  font-size: 15px;
}

h4 {
  margin: 0 0 8px;
  color: var(--muted);
  font-size: 12px;
  text-transform: uppercase;
}

.toolbar,
.filters {
  display: flex;
  align-items: center;
  gap: 8px;
}

.api-field {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
}

.api-field input {
  width: min(34vw, 340px);
}

input,
select {
  min-height: 36px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: #fff;
  color: var(--text);
  padding: 0 10px;
}

