.session-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.session-title {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  font-weight: 700;
}

.session-subtitle {
  margin-top: 6px;
  color: var(--muted);
  font-size: 12px;
}

.detail-panel,
.empty {
  min-height: 520px;
  padding: 20px;
}

.empty {
  display: grid;
  place-content: center;
  text-align: center;
}

.empty p {
  max-width: 440px;
  color: var(--muted);
}

.hidden {
  display: none;
}

.detail-header,
.columns {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 16px;
  align-items: start;
}

.columns {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.badge {
  border-radius: 999px;
  padding: 5px 10px;
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  white-space: nowrap;
}

.risk-low {
  background: var(--good);
}

.risk-medium {
  background: var(--warn);
}

.risk-high,
.risk-critical {
  background: var(--bad);
}

.score-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin: 20px 0;
}

.score-grid div {
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
}

.score-grid span {
  display: block;
  margin-bottom: 8px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
